+	require_linux_launch()?;
 	if unsafe { libc::geteuid() } == 0 {
 		bail!("supervisor must never execute as root");
 	}"},{"sha":"ddf507e092d36ce71b09e8e4cc2c73b65a0d34b7","filename":"src/jobctl_engine_scratch_tests.rs","status":"modified","additions":58,"deletions":1,"changes":59,"blob_url":"https://github.com/TrillionniumFoundation/hepta-runtime/blob/942d470d155c65ba7235eb19c5bbfd07f1ce2ad0/src%2Fjobctl_engine_scratch_tests.rs","raw_url":"https://github.com/TrillionniumFoundation/hepta-runtime/raw/942d470d155c65ba7235eb19c5bbfd07f1ce2ad0/src%2Fjobctl_engine_scratch_tests.rs","contents_url":"https://api.github.com/repos/TrillionniumFoundation/hepta-runtime/contents/src%2Fjobctl_engine_scratch_tests.rs?ref=942d470d155c65ba7235eb19c5bbfd07f1ce2ad0","patch":"@@ -8,11 +8,12 @@ use super::*;
